import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at register time naming the tool when inputSchema is invalid JSON Schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'invalid_schema_tool',
          description: 'Declares an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'invalid-type'}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/invalid_schema_tool/);
  });

  it('validates input against static and function-valued schemas before executing and never leaks offending values', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    let activeSchema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };

    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Get weather for a location',
        inputSchema: activeSchema,
      }),
      async input => {
        executorCalls += 1;
        return JSON.stringify(input);
      }
    );

    const missingResponse = await registry.execute('dynamic_weather', {});
    const wrongTypeResponse = await registry.execute('dynamic_weather', {location: 987654321});

    activeSchema = {
      type: 'object',
      properties: {zipCode: {type: 'number'}},
      required: ['zipCode'],
    };
    const updatedSchemaRejection = await registry.execute('dynamic_weather', {location: 'Paris'});
    const validResponse = await registry.execute('dynamic_weather', {zipCode: 75001, extra: 'kept'});

    expect({
      executorCalls,
      missingMentionsLocation: missingResponse.result.includes('location') && /required/i.test(missingResponse.result),
      wrongTypeMentionsFieldAndType:
        wrongTypeResponse.result.includes('location') && wrongTypeResponse.result.includes('string'),
      leakedValueInResult: wrongTypeResponse.result.includes('987654321'),
      leakedValueInLogs: recordedLogs.some(line => line.includes('987654321')),
      updatedSchemaMentionsZipCode:
        updatedSchemaRejection.result.includes('zipCode') && /required/i.test(updatedSchemaRejection.result),
      validResult: JSON.parse(validResponse.result),
    }).toEqual({
      executorCalls: 1,
      missingMentionsLocation: true,
      wrongTypeMentionsFieldAndType: true,
      leakedValueInResult: false,
      leakedValueInLogs: false,
      updatedSchemaMentionsZipCode: true,
      validResult: {zipCode: 75001, extra: 'kept'},
    });
  });
});

